CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('student','alumni','moderator','admin','super_admin');
CREATE TYPE user_status AS ENUM ('active','suspended','banned');
CREATE TYPE room_type AS ENUM ('global','cohort','alumni');
CREATE TYPE moderation_status AS ENUM ('pending','approved','rejected','removed');
CREATE TYPE report_status AS ENUM ('pending','resolved','dismissed');
CREATE TYPE announcement_audience AS ENUM ('all','cohort','alumni');
CREATE TYPE ban_type AS ENUM ('mute','temp_ban','permanent_ban');
CREATE TABLE cohorts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), graduation_year INTEGER UNIQUE NOT NULL CHECK (graduation_year BETWEEN 2000 AND 2100), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), college_id TEXT UNIQUE NOT NULL, college_email TEXT UNIQUE NOT NULL, enrollment_year INTEGER NOT NULL CHECK (enrollment_year BETWEEN 2000 AND 2100), program_code TEXT NOT NULL, roll_number TEXT NOT NULL, cohort_id UUID NOT NULL REFERENCES cohorts(id), role user_role NOT NULL DEFAULT 'student', status user_status NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE anonymous_identities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, display_name TEXT UNIQUE NOT NULL, avatar_seed TEXT, valid_from TIMESTAMPTZ NOT NULL DEFAULT now(), valid_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (valid_until IS NULL OR valid_until > valid_from));
CREATE INDEX idx_anonymous_identity_user ON anonymous_identities(user_id);
CREATE TABLE rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), type room_type NOT NULL, name TEXT NOT NULL, cohort_id UUID REFERENCES cohorts(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((type = 'cohort' AND cohort_id IS NOT NULL) OR (type <> 'cohort' AND cohort_id IS NULL)));
CREATE UNIQUE INDEX uniq_cohort_room ON rooms(cohort_id) WHERE type = 'cohort';
CREATE TABLE messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, sender_id UUID NOT NULL REFERENCES users(id), content TEXT NOT NULL CHECK (char_length(content) BETWEEN 1 AND 4000), reply_to_id UUID REFERENCES messages(id), moderation_status moderation_status NOT NULL DEFAULT 'approved', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), edited_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ);
CREATE INDEX idx_messages_room_time ON messages(room_id, created_at DESC, id DESC);
CREATE INDEX idx_messages_sender ON messages(sender_id, created_at DESC);
CREATE TABLE message_reactions (message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, reaction TEXT NOT NULL CHECK (reaction IN ('like','love','laugh','wow','sad','angry')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (message_id, user_id, reaction));
CREATE TABLE reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE, reporter_id UUID NOT NULL REFERENCES users(id), reason TEXT NOT NULL, description TEXT, status report_status NOT NULL DEFAULT 'pending', reviewed_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE INDEX idx_reports_status ON reports(status, created_at DESC);
CREATE TABLE bans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, type ban_type NOT NULL, reason TEXT NOT NULL, expires_at TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200), content TEXT NOT NULL, author_id UUID NOT NULL REFERENCES users(id), audience_type announcement_audience NOT NULL, cohort_id UUID REFERENCES cohorts(id), is_pinned BOOLEAN NOT NULL DEFAULT false, published_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((audience_type = 'cohort' AND cohort_id IS NOT NULL) OR (audience_type <> 'cohort' AND cohort_id IS NULL)));
CREATE INDEX idx_announcements_visibility ON announcements(audience_type, cohort_id, published_at DESC);
CREATE TABLE announcement_attachments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), announcement_id UUID NOT NULL REFERENCES announcements(id) ON DELETE CASCADE, storage_path TEXT NOT NULL, file_name TEXT NOT NULL, mime_type TEXT NOT NULL, file_size BIGINT NOT NULL CHECK (file_size > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id UUID, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_created ON audit_logs(created_at DESC);
CREATE TABLE notification_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, push_token TEXT UNIQUE NOT NULL, platform TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO cohorts (graduation_year) VALUES (2026),(2027),(2028),(2029),(2030),(2031),(2032),(2033) ON CONFLICT DO NOTHING;
INSERT INTO rooms (type, name) VALUES ('global','All College'),('alumni','Alumni');
INSERT INTO rooms (type, name, cohort_id) SELECT 'cohort', graduation_year::text || ' Batch', id FROM cohorts ON CONFLICT DO NOTHING;
